lemma minimal_complex_cardinality_euler
    {I : Ideal (R3 k)} {e : ℕ} (hA : IsTypeTwoLevel I e)
    (C : GradedMinimalFreeComplex I e hA) :
    @Fintype.card C.β₁ C.fintype₁ + @Fintype.card C.β₃ C.fintype₃ =
      @Fintype.card C.β₂ C.fintype₂ + 2

lemma inverseSystemKernelPiece_zero_of_neg
    {I : Ideal (R3 k)} {e : ℕ} (hA : IsTypeTwoLevel I e) {t : ℤ}
    (ht : t < 0) : inverseSystemKernelPiece hA t = ⊥

lemma signedMultiplicity_zero
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    (C : GradedMinimalFreeComplex I e hA) : signedMultiplicity C 0 = 0

lemma signedMultiplicity_one_nonpos
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    (C : GradedMinimalFreeComplex I e hA) : signedMultiplicity C 1 ≤ 0

lemma idealPieceWitness_ne_zero
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    (n : ℕ) (hn : idealPiece I n ≠ ⊥) : idealPieceWitness hA n hn ≠ 0

lemma idealPieceWitness_mem_ideal
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    (n : ℕ) (hn : idealPiece I n ≠ ⊥) : idealPieceWitness hA n hn ∈ I

lemma beta₂_nonempty_of_beta₃
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    (C : GradedMinimalFreeComplex I e hA) (a0 : C.β₃) : Nonempty C.β₂

lemma shiftSum_cutoff_mono (f : ℤ → ℤ) {t u u' : ℤ}
    (htu : t ≤ u) (huu' : u ≤ u') :
    shiftSum u' f t = shiftSum u f t

lemma pShift_ne_of_p_eq_zero
    {I : Ideal (R3 k)} {e : ℕ}
    {β₁ β₂ : Type*} [Fintype β₁] [Fintype β₂]
    (D : GradedResolutionDuality I e β₁ β₂) {d : ℤ}
    (hp : D.p d = 0) (i : β₁) : D.pShift i ≠ d

lemma quotientComponent_eq_zero_above {I : Ideal (R3 k)} {e n : ℕ}
    (hA : IsTypeTwoLevel I e) (hn : e < n) (x : R3 k ⧸ I) :
    quotientComponent I hA.homogeneous n x = 0

theorem sum_quotientComponent {I : Ideal (R3 k)} {e : ℕ}
    (hA : IsTypeTwoLevel I e) (x : R3 k ⧸ I) :
    (∑ n ∈ Finset.range (e + 1), quotientComponent I hA.homogeneous n x) = x

theorem sum_matlisComponent {I : Ideal (R3 k)} {e : ℕ}
    (hA : IsTypeTwoLevel I e) (phi : MatlisDual I) :
    (∑ n ∈ Finset.range (e + 1), matlisComponent I hA.homogeneous n phi) = phi

lemma finrank_reversedMatlisPiece {I : Ideal (R3 k)} {e d : ℕ}
    (hA : IsTypeTwoLevel I e) (hd : d ≤ e) :
    finrank k (reversedMatlisPiece hA d) = finrank k (quotPiece I (e - d))

lemma finrank_reversedMatlisPiece_zero {I : Ideal (R3 k)} {e : ℕ}
    (hA : IsTypeTwoLevel I e) :
    finrank k (reversedMatlisPiece hA 0) = 2

lemma quotPiece_disjoint {I : Ideal (R3 k)}
    (hI : I.IsHomogeneous (MvPolynomial.homogeneousSubmodule (Fin 3) k))
    {m n : ℕ} (hmn : m ≠ n) {x : R3 k ⧸ I}
    (hm : x ∈ quotPiece I m) (hn : x ∈ quotPiece I n) : x = 0

lemma matlisGenerator_mem_top {I : Ideal (R3 k)} {e : ℕ}
    (hA : IsTypeTwoLevel I e) (i : Fin 2) :
    matlisGenerator hA i ∈ matlisPiece I hA.homogeneous e

theorem inverseSystemPieceMap_surjective {I : Ideal (R3 k)} {e n : ℕ}
    (hA : IsTypeTwoLevel I e) (hne : n ≤ e) :
    Function.Surjective (inverseSystemPieceMap hA n)

@[simp] lemma inverseSystemMap_apply {I : Ideal (R3 k)} {e : ℕ}
    (hA : IsTypeTwoLevel I e) (u : Fin 2 → R3 k) :
    inverseSystemMap hA u = ∑ i : Fin 2, u i • matlisGenerator hA i

lemma homogeneousComponent_mul_left_eq_zero {m n : ℕ} {r f : R3 k}
    (hr : MvPolynomial.IsHomogeneous r m) (hnm : n < m) :
    MvPolynomial.homogeneousComponent n (r * f) = 0

lemma inverseSystemMap_vectorComponent_high {I : Ideal (R3 k)} {e d : ℕ}
    (hA : IsTypeTwoLevel I e) (hed : e < d) (u : Fin 2 → R3 k) :
    inverseSystemMap hA (vectorHomogeneousComponent d u) = 0

lemma inverseSystemKernel_component_mem {I : Ideal (R3 k)} {e d : ℕ}
    (hA : IsTypeTwoLevel I e) {u : Fin 2 → R3 k}
    (hu : u ∈ inverseSystemKernel hA) :
    vectorHomogeneousComponent d u ∈ inverseSystemKernel hA

lemma homogeneousComponent_mul_right_eq_zero {m n : ℕ} {r f : R3 k}
    (hr : MvPolynomial.IsHomogeneous r m) (hnm : n < m) :
    MvPolynomial.homogeneousComponent n (f * r) = 0

lemma MinimalSpanningFamily.erase_not_span
    {R M G : Type*} [CommRing R] [AddCommGroup M] [Module R M]
    [Fintype G] {P : Submodule R M} {generator : G → M}
    {hspan : Submodule.span R (Set.range generator) = P}
    (F : MinimalSpanningFamily P generator hspan) {i : G}
    (hi : i ∈ F.indices) :
    Submodule.span R (generator '' (F.indices.erase i : Set G)) ≠ P

lemma MinimalSpanningFamily.mem_span_of_mem
    {R M G : Type*} [CommRing R] [AddCommGroup M] [Module R M]
    [Fintype G] {P : Submodule R M} {generator : G → M}
    {hspan : Submodule.span R (Set.range generator) = P}
    (F : MinimalSpanningFamily P generator hspan) {i : G}
    (hi : i ∈ F.indices) : generator i ∈ P

lemma MinimalSpanningFamily.not_mem_span_erase
    {R M G : Type*} [CommRing R] [AddCommGroup M] [Module R M]
    [Fintype G] {P : Submodule R M} {generator : G → M}
    {hspan : Submodule.span R (Set.range generator) = P}
    (F : MinimalSpanningFamily P generator hspan) {i : G}
    (hi : i ∈ F.indices) :
    generator i ∉
      Submodule.span R (generator '' (F.indices.erase i : Set G))

lemma MinimalSpanningFamily.mem_span_erase_of_unit_relation
    {R M G : Type*} [CommRing R] [AddCommGroup M] [Module R M]
    [Fintype G] {P : Submodule R M} {generator : G → M}
    {hspan : Submodule.span R (Set.range generator) = P}
    (F : MinimalSpanningFamily P generator hspan) {i : G}
    (hi : i ∈ F.indices) (coeff : F.indices → R)
    (hunit : IsUnit (coeff ⟨i, hi⟩))
    (hrel : ∑ j, coeff j • generator j.1 = 0) :
    generator i ∈
      Submodule.span R (generator '' (F.indices.erase i : Set G))

lemma second_minimal_relation_mem_irrelevant
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    {H : HomogeneousFirstRelations hA}
    (S : HomogeneousSecondRelations H)
    [fintypeS : Fintype S.γ]
    {F : MinimalSpanningFamily (LinearMap.ker H.d₁) S.generator S.span_eq}
    (c : F.indices → R3 k)
    (hrel : ∑ a, c a • S.generator a.1 = 0) :
    ∀ a, c a ∈ irrelevantIdeal k

lemma second_syzygy_projective
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    {H : HomogeneousFirstRelations.{uk, 0} hA}
    (S : HomogeneousSecondRelations.{uk, 0, 0} H) :
    Module.Projective (R3 k) (LinearMap.ker S.d₂)

lemma third_minimal_relation_mem_irrelevant
    {I : Ideal (R3 k)} {e : ℕ} {hA : IsTypeTwoLevel I e}
    {H : HomogeneousFirstRelations hA}
    {S : HomogeneousSecondRelations H}
    (T : HomogeneousThirdRelations S)
    [fintypeT : Fintype T.δ]
    {F : MinimalSpanningFamily (LinearMap.ker S.d₂) T.generator T.span_eq}
    (c : F.indices → R3 k)
    (hrel : ∑ a, c a • T.generator a.1 = 0) :
    ∀ a, c a ∈ irrelevantIdeal k

lemma third_kernel_finrank (C : GradedMinimalFreeComplex I e hA) :
    Module.finrank (R3 k) (LinearMap.ker C.d₂) =
      @Fintype.card C.β₃ C.fintype₃

lemma isHomogeneous_mem_irrelevant_eq_zero {f : R3 k}
    (hmem : f ∈ irrelevantIdeal k)
    (hhom : MvPolynomial.IsHomogeneous f 0) : f = 0

lemma quotPiece_X_mul {I : Ideal (R3 k)} (j : Fin 3) {n : ℕ} {a : R3 k ⧸ I}
    (ha : a ∈ quotPiece I n) :
    Ideal.Quotient.mk I (X j) * a ∈ quotPiece I (n + 1)

lemma GorensteinQuotientHF.bounds {B : ℤ → ℤ} {E : ℤ}
    (hgor : GorensteinQuotientHF k B E) :
    (∀ t : ℤ, t < 0 → B t = 0) ∧ (∀ t, 0 ≤ B t) ∧ (∀ t, B t ≤ Nz t)

lemma isHomogeneous_mem_pow_idealOfVars {f : R3 k} {m r : ℕ}
    (hf : MvPolynomial.IsHomogeneous f m) (hrm : r ≤ m) :
    f ∈ MvPolynomial.idealOfVars (Fin 3) k ^ r

lemma isHomogeneous_eq_zero_of_mem_succ_pow_idealOfVars {f : R3 k} {n : ℕ}
    (hf : MvPolynomial.IsHomogeneous f n)
    (hmem : f ∈ MvPolynomial.idealOfVars (Fin 3) k ^ (n + 1)) : f = 0

lemma δ₂_kernel_eq_span_circuit (D : GradedResolutionDuality I e β₁ β₂) :
    LinearMap.ker D.δ₂ =
      Submodule.span (FractionRing (R3 k)) {D.circuit}

lemma idealHilb_eq_annihilator
    (C : CriticalBranchCertificate D d) {z : ℤ}
    (hz : z ≤ d - (C.a : ℤ)) : idealHilb C.J z = idealHilb C.Ann z

lemma mem_range_d₁_pi_of_entries_mem {f : ι → R3 k}
    (hf : ∀ j, f j ∈ MvPolynomial.idealOfVars (Fin 3) k) :
    f ∈ LinearMap.range (d₁ k (ι → R3 k))

lemma Q_mem_span_of_support (f : R3 k)
    (h : ∀ m ∈ f.support, witnessPred m ∨ m = mono 2 0 0 ∨ m = mono 0 1 1) :
    Q k f ∈ Submodule.span k {wu k, wv k}
